    def _build_ru_ws_configuration(self, tl):
        """
        Build hub ws configuration from TAF config model.

        :param tl: Taf configuration.
        :return: Nothing
        """
        self._build_gnb_ru_ws_configuration(tl)
        self._build_enb_ru_ws_configuration(tl)

    def _build_gnb_ru_ws_configuration(self, tl):  # noqa: C901
        """
        Build gnb hub ws configuration from TAF config model.

        :param tl: Taf configuration.
        :return: Nothing
        """
        if hasattr(tl, "gnbs") and tl.gnbs:
            for ru_details in self._get_gnb_and_ru(tl):
                device_name = None
                if len(ru_details) == 6:
                    gnb_id, gnb, du_id, du, ru_id, ru = ru_details
                elif len(ru_details) == 8:
                    gnb_id, gnb, du_id, du, common_unit_id, common_unit, ru_id, ru = ru_details
                    device_name = "GNB{}_DU{}_CU{}_RU{}_WS".format(gnb_id, du_id, common_unit_id, ru_id)
                else:
                    gnb_id, gnb, du_id, du, com_unit_id, com_unit, cap_unit_id, cap_unit, ru_id, ru = ru_details
                    device_name = "GNB{}_DU{}_CU{}_CPTY{}_RU{}_WS".format(gnb_id, du_id,
                                                                          com_unit_id, cap_unit_id, ru_id)

                if ru.lmp_connection and ru.lmp_connection.proxy and device_name:
                    self.moler_devices.add_remote_unix_configuration(
                        device_name=device_name,
                        host=ru.lmp_connection.proxy.addr,
                        login=ru.lmp_connection.proxy.username,
                        password=ru.lmp_connection.proxy.password)
                try:
                    if is_instance_of_class(ru, 'SC5GRadio'):
                        self.moler_devices.add_hub_ws_configuration(
                            device_name="GNB{}_HUB{}_WS".format(gnb_id, ru_id),
                            host=ru.sc_radio_connection_details.ssh.proxy.addr,
                            login=ru.sc_radio_connection_details.ssh.proxy.username,
                            password=ru.sc_radio_connection_details.ssh.proxy.password)
                except (KeyError, AttributeError, TypeError) as ex:
                    self.logger.warning(self._parse_output_message(exception=ex,
                                                                   device_name="GNB{}_HUB{}_WS".format(gnb_id, ru_id)))

    def _build_enb_ru_ws_configuration(self, tl):
        """
        Build enb hub ws configuration from TAF config model.

        :param tl: Taf configuration.
        :return: Nothing
        """
        if hasattr(tl, "enbs") and tl.enbs:
            for enb_id, enb in enumerate(tl.enbs, 0):
                if is_instance_of_class(enb, "RealEnb"):
                    self._build_enb_rms_ws_configuration(enb_id, enb)

    def _build_enb_rms_ws_configuration(self, enb_id, enb):
        if hasattr(enb, "rms") and enb.rms:
            for rms_id, rms in self._get_enb_rms(enb):
                try:
                    if is_instance_of_class(rms, "SC4GRadio"):
                        self.moler_devices.add_hub_ws_configuration(
                            device_name="ENB{}_HUB{}_WS".format(enb_id, rms_id),
                            host=rms.sc_radio_connection_details.ssh.proxy.addr,
                            login=rms.sc_radio_connection_details.ssh.proxy.username,
                            password=rms.sc_radio_connection_details.ssh.proxy.password,
                        )
                except (KeyError, AttributeError, TypeError) as ex:
                    self.logger.warning(self._parse_output_message(exception=ex, device_name="ENB{}_HUB{}_WS".format(enb_id, rms_id)))

    @staticmethod  # noqa: C901
    def _get_gnb_and_ru(tl):  # noqa: C901
        for gnb_id, gnb in enumerate(tl.gnbs, 0):
            for du_id, du in enumerate(gnb.dus, 0):
                airscale = du.airscale
                if airscale.common_units:
                    cus = airscale.common_units
                    for common_unit_id, common_unit in enumerate(cus, 0):
                        if common_unit.rus:
                            # It's only for specific HW like FSMF where we had only SMOD
                            for ru_id, ru in enumerate(common_unit.rus, 0):
                                yield gnb_id, gnb, du_id, du, common_unit_id, common_unit, ru_id, ru
                        for capacity_unit_id, capacity_unit in enumerate(common_unit.capacity_units, 0):
                            if capacity_unit.rus:
                                # It's Default configuration - RUs should be configured under capacity units(BBMOD)
                                for ru_id, ru in enumerate(capacity_unit.rus, 0):
                                    yield gnb_id, gnb, du_id, du, common_unit_id, common_unit, capacity_unit_id, capacity_unit, ru_id, ru
                elif airscale.core_units:
                    cus = airscale.core_units
                    for core_unit_id, core_unit in enumerate(cus, 0):
                        if core_unit.rus:
                            # It's only for specific HW like ASOE where we had only SMOD
                            for ru_id, ru in enumerate(core_unit.rus, 0):
                                yield gnb_id, gnb, du_id, du, core_unit_id, core_unit, ru_id, ru
                if du.rus:
                    # It's deprecated and should not be used anymore  - RUs should be configured under capacity units(BBMOD)
                    for ru_id, ru in enumerate(du.rus, 0):
                        yield gnb_id, gnb, du_id, du, ru_id, ru

    @staticmethod
    def _get_enb_rms(enb):
        for rms_id, rms in enumerate(enb.rms, 0):
            yield rms_id, rms

    @staticmethod
    def _get_gnb_and_du(tl):
        for gnb_id, gnb in enumerate(tl.gnbs, 0):
            for du_id, du in enumerate(gnb.dus, 0):
                cus = du.airscale.common_units
                if not cus:
                    cus = du.airscale.core_units
                for common_unit_id, common_unit in enumerate(cus, 0):
                    yield gnb_id, gnb, du_id, du, common_unit_id, common_unit

    def _build_ue_pc_configuration(self, tl):
        """
        Build ue configuration from TAF config model or ute_ue yaml file.

        :param tl: Taf configuration.
        :return: None
        """

        ue_config_from_yaml = self._get_ue_config()
        if ue_config_from_yaml:
            self.__build_ue_pc_configuration_from_yaml(ue_config_from_yaml)
        else:
            self.__build_ue_pc_configuration_from_taf(tl)

    def __build_ue_pc_configuration_from_yaml(self, ue_config):
        """
        Build UE_PC configuration from yaml configuration file.

        :param ue_config: dict with ue configuration from yaml file.
        :return: None
        """
        ue_index = 0
        for ue_pool in ue_config['UE_POOLS']:
            inline_config = ue_config['UE_POOLS'][ue_pool]['inline_config']
            for ue in inline_config:
                if ue_pool in ['IPhoneUePool', 'TafUeIphonePool']:
                    ue_index = ue_index + 1
                    continue
                try:
                    ue_pc_params = inline_config[ue]['CONSTRUCTOR_PARAMETERS']['configuration']
                    login = ue_pc_params.get('login', ue_pc_params.get('ue_pc_login'))
                    quoted_login = shlex.quote(login) if login is not None else 'None'
                    method_params = {
                        'device_name': "UE{}_PC".format(ue_index),
                        'host': ue_pc_params.get('ue_pc_ip', ue_pc_params.get('ue_pc_address')),
                        'login': ue_pc_params.get('login', ue_pc_params.get('ue_pc_login')),
                        'password': ue_pc_params.get('password', ue_pc_params.get('ue_pc_password')),
                        "prompt_after_login": r'^\$\s+$',
                        "set_prompt": rf"export PS1='{quoted_login}@\h:\w> '",
                    }
                    self.moler_devices.add_remote_unix_configuration(**method_params)
                except (KeyError, AttributeError, TypeError) as ex:
                    self.logger.warning(self._parse_output_message(exception=ex,
                                                                   device_name="UE{}_PC".format(ue_index)))
                ue_index = ue_index + 1

    def __build_ue_pc_configuration_from_taf(self, tl):
        """
        Build ue configuration from TAF config model.

        :param tl: Taf configuration.
        :return: None
        """

        # ssh_options = '-o ServerAliveInterval=7 -o ServerAliveCountMax=2 '\
        #               '-o KexAlgorithms=+diffie-hellman-group1-sha1 -c aes128-cbc'

        if hasattr(tl, "ues") and tl.ues:
            for index, ue in enumerate(tl.ues, 0):
                try:
                    if hasattr(ue, 'ssh_connection_details') and ue.ssh_connection_details:
                        credentials = {
                            'host': ue.ssh_connection_details.addr,
                            'login': ue.ssh_connection_details.username,
                            'password': ue.ssh_connection_details.password,
                        }
                    else:
                        credentials = {
                            'host': ue.ue_pc_address,
                            'login': getattr(ue, 'ue_pc_login', None),
                            'password': getattr(ue, 'ue_pc_password', None),
                        }
                    quoted_login = shlex.quote(credentials['login']) if credentials['login'] is not None else 'None'
                    method_params = {
                        'device_name': "UE{}_PC".format(index),
                        # 'options': ssh_options,
                        "prompt_after_login": r'^\$\s+$',
                        "set_prompt": rf"export PS1='{quoted_login}@\h:\w> '",
                    }
                    method_params.update(credentials)
                    self.moler_devices.add_remote_unix_configuration(**method_params)
                except (KeyError, AttributeError, TypeError) as ex:
                    self.logger.warning(self._parse_output_message(exception=ex, device_name="UE{}_PC".format(index)))

    def _build_app_server_configuration(self, tl):
        """
        Build app_server configuration from TAF config model or ute_ue yaml file.

        :param tl: Taf configuration.
        :return: None
        """

        ue_config_from_yaml = self._get_ue_config()
        if ue_config_from_yaml:
            self.__build_app_server_configuration_from_yaml(ue_config_from_yaml)
        else:
            self._build_app_server_configuration_from_taf(tl)

    def __build_app_server_configuration_from_yaml(self, ue_config):  # noqa: C901
        """
        Build APP_SERVER configuration from yaml configuration file.

        :param ue_config: dict with ue configuration from yaml file.
        :return: None
        """
        app_servers_params = []
        ue_index = 0
        for ue_pool in ue_config['UE_POOLS']:
            inline_config = ue_config['UE_POOLS'][ue_pool]['inline_config']
            for ue in inline_config:
                try:
                    data_transfer = inline_config[ue]['CONSTRUCTOR_PARAMETERS']['configuration']['data_transfer']
                    if ue_pool in ['TafUeAndroidPool']:
                        app_server_index = 0
                        for protocol in ['iperf', 'ping', 'ftp']:
                            if protocol in data_transfer:
                                app_servers_params.append(
                                    {'app_server': data_transfer['iperf']['app_server'],
                                     'device_name': "APP_SERVER{}_{}".format(ue_index, app_server_index)})
                                app_server_index = app_server_index + 1
                    elif 'ssh' in data_transfer:
                        app_servers_params.append({'app_server': data_transfer['ssh']})
                    elif 'iperf' in data_transfer:
                        app_servers_params.append({'app_server': data_transfer['iperf']['app_server']})
                    elif 'app_servers' in data_transfer:
                        for app_server in data_transfer['app_servers']:
                            app_servers_params.append({'app_server': data_transfer['app_servers'][app_server]})

                except (KeyError, AttributeError, TypeError) as ex:
                    self.logger.warning(self._parse_output_message(exception=ex,
                                                                   device_name="APP_SERVER"))
                ue_index = ue_index + 1

        for index, app_server in enumerate(app_servers_params, 0):
            method_params = {
                'device_name': app_server.get('device_name', "APP_SERVER{}".format(index)),
                'host': app_server['app_server'].get('host', app_server['app_server'].get('address', None)),
                'login': app_server['app_server']['user'],
                'password': app_server['app_server']['password'],
            }
            self.moler_devices.add_remote_unix_configuration(**method_params)

    def _build_app_server_configuration_from_taf(self, tl):
        """
        Build app_server configuration from TAF config model.

        :param tl: Taf configuration.
        :return: None
        """
        # ssh_options = '-o ServerAliveInterval=7 -o ServerAliveCountMax=2 '\
        #               '-o KexAlgorithms=+diffie-hellman-group1-sha1 -c aes128-cbc'

        if hasattr(tl, "ues") and tl.ues:
            for ue_index, ue in enumerate(tl.ues, 0):
                try:
                    if hasattr(ue, 'iperf_details'):
                        app_server_params = ue.iperf_details.ssh_connection_details
                        method_params = {
                            'device_name': "APP_SERVER{}".format(ue_index),
                            'host': app_server_params.addr,
                            'login': app_server_params.username,
                            'password': app_server_params.password,
                            # 'options': ssh_options,
                        }
                        self.moler_devices.add_remote_unix_configuration(**method_params)
                    else:
                        for app_server_index, data_transfer in enumerate(ue.data_transfer, 0):
                            method_params = {
                                'device_name': "APP_SERVER{}_{}".format(ue_index, app_server_index),
                                'host': data_transfer.app_server.address,
                                'login': data_transfer.app_server.user,
                                'password': data_transfer.app_server.password,
                                'prompt': data_transfer.app_server.expected_prompt
                            }
                            self.moler_devices.add_remote_unix_configuration(**method_params)
                except (KeyError, AttributeError, TypeError) as ex:
                    self.logger.warning(self._parse_output_message(exception=ex,
                                                                   device_name="APP_SERVER{}".format(ue_index)))

    def _build_at_remote_configuration(self, tl):
        """
        Build AtRemote configuration from TAF config model or yaml.

        :param tl: Taf configuration.
        :return: None
        """
        ue_config_from_yaml = self._get_ue_config()
        if ue_config_from_yaml:
            self._build_at_remote_configuration_from_yaml(ue_config_from_yaml)
        else:
            self._build_at_remote_configuration_from_taf(tl)

    def _build_at_remote_configuration_from_yaml(self, ue_config):
        """
        Build AtRemote configuration from yaml configuration file.

        :param ue_config: dict with ue configuration from yaml file.
        :return: None
        """
        for ue_pool in ue_config['UE_POOLS']:
            inline_config = ue_config['UE_POOLS'][ue_pool]['inline_config']
            for index, ue in enumerate(inline_config, 0):
                if "AT_BASED_UE" in ue:
                    try:
                        ue_pc_params = inline_config[ue]['CONSTRUCTOR_PARAMETERS']['configuration']
                        method_params = {
                            'device_name': "UE{}_AT".format(index),
                            'host': ue_pc_params['ue_pc_ip'],
                            'login': ue_pc_params['login'],
                            'password': ue_pc_params['password'],
                            'serial_com': ue_pc_params['serial_com'],
                            'set_prompt': r'export PS1="${PS1::-4} # "'
                        }
                        self.moler_devices.add_at_remote_configuration(**method_params)
                    except (KeyError, AttributeError, TypeError) as ex:
                        self.logger.warning(self._parse_output_message(exception=ex,
                                                                       device_name="UE{}_AT".format(index)))

    def _build_at_remote_configuration_from_taf(self, tl):
        """
        Build AtRemote configuration from TAF config model.

        :param tl: Taf configuration.
        :return: None
        """
        if hasattr(tl, "ues") and tl.ues:
            for index, ue in enumerate(tl.ues, 0):
                if hasattr(ue, "capabilities") and ue.capabilities is not None and "AT_CMD_UE" in ue.capabilities:
                    try:
                        ue_pc_params = ue.ssh_connection_details
                        method_params = {
                            'device_name': "UE{}_AT".format(index),
                            'host': ue_pc_params.addr,
                            'login': ue_pc_params.username,
                            'password': ue_pc_params.password,
                            'serial_com': str(ue.serial_com),
                            'set_prompt': r'export PS1="${PS1::-4} # "'
                        }
                        self.moler_devices.add_at_remote_configuration(**method_params)
                    except (KeyError, AttributeError, TypeError) as ex:
                        self.logger.warning(self._parse_output_message(exception=ex,
                                                                       device_name="UE{}_AT".format(index)))

    def _build_nom_configuration_from_taf(self, tl):
        """
        Build AtRemote configuration from TAF config model.

        :param tl: Taf configuration.
        :return: None
        """
        if hasattr(tl, "nms") and tl.nms and tl.nms.nom:
            device_name = 'NOM'
            try:
                ssh_params = tl.nms.nom.ssh_connections_info[0]
                method_params = {
                    'device_name': device_name,
                    'host': ssh_params.addr,
                    'login': ssh_params.username,
                    'password': ssh_params.password,
                    'private_key': ssh_params.private_key
                }
                self.moler_devices.add_nom_configuration(**method_params)
            except (KeyError, AttributeError, TypeError) as ex:
                self.logger.warning(self._parse_output_message(exception=ex,
                                                               device_name=device_name))

    @staticmethod
    def _get_ue_config():
        """
        Get UE configuration from yaml file.
        :return: UE config if exists, else None
        """
        from collections import OrderedDict

        def ordered_load(stream, Loader=yaml.SafeLoader, object_pairs_hook=OrderedDict):
            class OrderedLoader(Loader):
                pass

            def construct_mapping(loader, node):
                loader.flatten_mapping(node)
                return object_pairs_hook(loader.construct_pairs(node))

            OrderedLoader.add_constructor(
                yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG,
                construct_mapping)
            return yaml.load(stream, OrderedLoader)

        ue_config_abs_path = os.getenv("ABSTRACT_LIB_CONFIG")
        ue_config = None
        if ue_config_abs_path:
            with open(ue_config_abs_path) as ta_ue_config:
                ue_config = ordered_load(ta_ue_config)
        return ue_config

    # [2a00:8a02:60:1c::1:229]
    _re_ipv6_with_square_brackets = re.compile(r"\[(?P<ADDRESS>[a-f\d:]+)\]", re.IGNORECASE)

    @classmethod
    def _convert_ip_address(cls, address):
        """
        Convert IP v6 address with square brackets into address IP v6 without square brackets.
        :param address: address to convert
        :return: converted address
        """
        ret_address = address
        m = re.search(MolerConverter._re_ipv6_with_square_brackets, address)
        if m:
            ret_address = m.group("ADDRESS")
        return ret_address

    @staticmethod
    def _parse_output_message(exception, device_name):
        """
        Parses the output message for the MolerConverterException.
        :param exception:       Caught exception which the information is parsed from
        :param device_name:     Name of the device which configuration building failed
        :return:                Parsed output message
        """
        prefix = '[MolerConverterException] Building device {} failed due to {}:'.\
            format(device_name, exception.__class__.__name__)
        output_message = traceback.format_exc()
        return '{}\n {}'.format(prefix, output_message)
